void status_system_init( void )
{
    memset( &status_ss           , 0x00 , sizeof( struct s_Ss            ) );
    memset( &status_rs           , 0x00 , sizeof( struct s_Rs            ) );
    memset( &status_sense        , 0x00 , sizeof( struct s_Sense         ) );
    memset( &status_sense_source , 0x00 , sizeof( struct s_Sense_Source  ) );
    memset( &status_rke_use      , 0x00 , sizeof( struct s_Rke_Use       ) );

    status_rs_takeover = FALSE;
}

